// Oeste Breadcrumb — Topanga theme (v0.4.7).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Topanga tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/src/index.js
// Docs: https://oeste.hiddeninwest.com/#/components/breadcrumb

export function Breadcrumb({ items = [], ariaLabel = "Breadcrumb" }) {
  return (
    <nav aria-label={ariaLabel}>
      <ol className="flex flex-wrap items-center gap-2">
        {items.map((item, i) => {
          const current = i === items.length - 1;
          return (
            <li key={i} className="flex items-center gap-2">
              {i > 0 && <span aria-hidden="true" className="text-[#706963] dark:text-[#9e968f]">/</span>}
              {current || !item.href
                ? <span aria-current="page" className="font-semibold text-[#1c1917] dark:text-[#f5f3ef]">{item.label}</span>
                : <a href={item.href} className="text-[#1c1917] underline-offset-2 hover:underline dark:text-[#f5f3ef]">{item.label}</a>}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}
